#!/bin/sh
# Built by build.sh from Shell sources. Run: sudo sh remnamanager.sh
set -eu
[ "$(uname -s)" = Linux ] && [ "$(id -u)" -eq 0 ] || { echo 'Нужны Linux и запуск от root.' >&2; exit 1; }
umask 077
root=/opt/remnamanager
mkdir -p "$root"
chmod 700 "$root"
exec 8>"$root/install.lock"
flock -n 8 || { echo 'Другой установщик уже работает.' >&2; exit 1; }
exec 9>"$root/manager.lock"
flock -n 9 || { echo 'Менеджер уже работает. Закройте его перед обновлением.' >&2; exit 1; }
temporary=$(mktemp -d "$root/install.XXXXXXXX")
trap 'rm -rf -- "$temporary"' EXIT HUP INT TERM
sed '1,/^__REMNAMANAGER_PAYLOAD__$/d' "$0" | base64 -d >"$temporary/app.tar"
printf '%s  %s\n' '77e8dd4d80bb212819a580285283e7da6c38a5d3497dcd20726ef132db0e2300' "$temporary/app.tar" | sha256sum -c - >/dev/null
mkdir "$temporary/app"
tar --no-same-owner -xf "$temporary/app.tar" -C "$temporary/app"
if [ -L "$root/app" ]; then echo 'Каталог приложения не должен быть символьной ссылкой.' >&2; exit 1; fi
backup=''
if [ -d "$root/app" ]; then
    backup="$root/versions/$(date +%Y%m%d-%H%M%S)-install-$$"
    mkdir -p "$backup"
    version='неизвестна'
    if [ -f "$root/app/VERSION" ] && grep -Eq '^[0-9]{1,5}\.[0-9]{1,5}\.[0-9]{1,5}$' "$root/app/VERSION"; then version=$(cat "$root/app/VERSION"); fi
    printf '{"version":"%s","date":"%s"}\n' "$version" "$(date -u +%FT%TZ)" >"$backup/metadata.json"
    mv "$root/app" "$backup/app"
fi
if ! mv "$temporary/app" "$root/app"; then
    if [ -n "$backup" ]; then mv "$backup/app" "$root/app"; fi
    echo 'Не удалось установить приложение; прежний каталог возвращён.' >&2
    exit 1
fi
rm -rf -- "$temporary"
trap - EXIT HUP INT TERM
flock -u 9
exec 9>&-
flock -u 8
exec 8>&-
exec bash "$root/app/manager.sh" "$@"
exit 1
